## Task 2: Create codx-junior DaisyUI Themes (Dark & Light)

I've separated the themes into dedicated files for better maintainability and modularity. Both dark and light variants maintain brand consistency while respecting user preference.

### Step 1: Create the Dark Theme File

```css client/src/assets/themes/codx-junior-dark.css
/* codx-junior Dark DaisyUI Theme */
/* Brand Colors: #cc0099 (primary), #8f008f (secondary) */

:root[data-theme="codx-junior-dark"] {
  /* Dark neutral base */
  --color-base-100: rgba(26, 26, 46, 1);
  --color-base-200: rgba(36, 36, 56, 1);
  --color-base-300: rgba(46, 46, 66, 1);
  --color-base-content: rgba(245, 245, 250, 1);

  /* Primary: codx magenta (#cc0099) - boosted lightness for dark background */
  --color-primary: rgba(204, 0, 153, 1);
  --color-primary-content: rgba(26, 26, 46, 1);

  /* Secondary: codx purple (#8f008f) - elevated for visibility */
  --color-secondary: rgba(165, 50, 165, 1);
  --color-secondary-content: rgba(245, 245, 250, 1);

  /* Accent: Vibrant magenta complement */
  --color-accent: rgba(230, 50, 180, 1);
  --color-accent-content: rgba(26, 26, 46, 1);

  /* Neutral grays - dark mode optimized */
  --color-neutral: rgba(122, 122, 140, 1);
  --color-neutral-content: rgba(245, 245, 250, 1);

  /* Semantic colors - adjusted for dark backgrounds */
  --color-info: rgba(100, 200, 255, 1);
  --color-info-content: rgba(26, 26, 46, 1);
  --color-success: rgba(80, 220, 100, 1);
  --color-success-content: rgba(26, 26, 46, 1);
  --color-warning: rgba(255, 200, 50, 1);
  --color-warning-content: rgba(26, 26, 46, 1);
  --color-error: rgba(255, 100, 100, 1);
  --color-error-content: rgba(26, 26, 46, 1);

  /* Border radius harmony */
  --radius-selector: 0.75rem;
  --radius-field: 0.375rem;
  --radius-box: 0.5rem;

  /* Sizing */
  --size-selector: 0.25rem;
  --size-field: 0.25rem;

  /* Effects */
  --border: 1px;
  --depth: 1;
  --noise: 0;
}

.codx-primary {
  color: rgba(204, 0, 153, 1);
}

.codx-secondary {
  color: rgba(143, 0, 143, 1);
}

div[data-reka-popper-content-wrapper] {
  z-index: 2 !important;
}
```

### Step 2: Create the Light Theme File

```css client/src/assets/themes/codx-junior-light.css
/* codx-junior Light DaisyUI Theme */
/* Brand Colors: #cc0099 (primary), #8f008f (secondary) */

:root[data-theme="codx-junior-light"] {
  /* Light neutral base */
  --color-base-100: rgba(255, 255, 255, 1);
  --color-base-200: rgba(245, 245, 250, 1);
  --color-base-300: rgba(235, 235, 245, 1);
  --color-base-content: rgba(26, 26, 46, 1);

  /* Primary: codx magenta (#cc0099) */
  --color-primary: rgba(204, 0, 153, 1);
  --color-primary-content: rgba(255, 255, 255, 1);

  /* Secondary: codx purple (#8f008f) */
  --color-secondary: rgba(143, 0, 143, 1);
  --color-secondary-content: rgba(255, 255, 255, 1);

  /* Accent: Vibrant magenta complement */
  --color-accent: rgba(220, 40, 170, 1);
  --color-accent-content: rgba(255, 255, 255, 1);

  /* Neutral grays */
  --color-neutral: rgba(130, 130, 150, 1);
  --color-neutral-content: rgba(255, 255, 255, 1);

  /* Semantic colors */
  --color-info: rgba(70, 150, 220, 1);
  --color-info-content: rgba(255, 255, 255, 1);
  --color-success: rgba(60, 180, 80, 1);
  --color-success-content: rgba(255, 255, 255, 1);
  --color-warning: rgba(255, 180, 40, 1);
  --color-warning-content: rgba(30, 30, 50, 1);
  --color-error: rgba(240, 80, 80, 1);
  --color-error-content: rgba(255, 255, 255, 1);

  /* Border radius harmony */
  --radius-selector: 0.75rem;
  --radius-field: 0.375rem;
  --radius-box: 0.5rem;

  /* Sizing */
