/* codx-junior Light DaisyUI Theme */
/* Brand Colors: #cc0099 (primary), #8f008f (secondary) */

:root[data-theme="codx-junior-light"] {
  /* Light neutral base - brightened for readability */
  --color-base-100: rgba(255, 255, 255, 1);
  --color-base-200: rgba(250, 250, 252, 1);
  --color-base-300: rgba(240, 240, 245, 1);
  --color-base-content: rgba(20, 20, 30, 1);

  /* Primary: codx magenta (#cc0099) */
  --color-primary: rgba(204, 0, 153, 1);
  --color-primary-content: rgba(255, 255, 255, 1);

  /* Secondary: codx purple (#8f008f) */
  --color-secondary: rgba(143, 0, 143, 1);
  --color-secondary-content: rgba(255, 255, 255, 1);

  /* Accent: Vibrant magenta complement */
  --color-accent: rgba(220, 40, 170, 1);
  --color-accent-content: rgba(255, 255, 255, 1);

  /* Neutral grays - light mode optimized */
  --color-neutral: rgba(140, 140, 160, 1);
  --color-neutral-content: rgba(255, 255, 255, 1);

  /* Semantic colors - standard brightness for light backgrounds */
  --color-info: rgba(70, 150, 220, 1);
  --color-info-content: rgba(255, 255, 255, 1);
  --color-success: rgba(60, 180, 80, 1);
  --color-success-content: rgba(255, 255, 255, 1);
  --color-warning: rgba(255, 180, 40, 1);
  --color-warning-content: rgba(40, 40, 60, 1);
  --color-error: rgba(240, 80, 80, 1);
  --color-error-content: rgba(255, 255, 255, 1);

  /* Border radius harmony */
  --radius-selector: 0.75rem;
  --radius-field: 0.375rem;
  --radius-box: 0.5rem;

  /* Sizing */
  --size-selector: 0.25rem;
  --size-field: 0.25rem;

  /* Effects */
  --border: 1px;
  --depth: 1;
  --noise: 0;
}

.codx-primary {
  color: rgba(204, 0, 153, 1);
}

.codx-secondary {
  color: rgba(143, 0, 143, 1);
}

div[data-reka-popper-content-wrapper] {
  z-index: 2 !important;
}

@import "tailwindcss";
@plugin "@tailwindcss/typography";
@plugin "daisyui" {
  themes: all;
}

/* Import codx-junior themes */
@import "./themes/codx-junior-dark.css";
@import "./themes/codx-junior-light.css";

messages.content:
Let's override existing DaisyUI ones with codx-junior colors.
Create a daisy-override.css file overriding all themes in the list adding codx-junior colors from base.css


Example: 
```
@import "tailwindcss";
@plugin "daisyui";
@plugin "daisyui/theme" {
  name: "light";
  default: true;
  --color-primary: blue;
  --color-secondary: teal;
}
```


